{
  "name": "PawPulse AI - Virtual Pet Care Assistant",
  "description": "A comprehensive AI-powered pet care platform that provides breed-specific advice, tracks health metrics, manages vaccination schedules, and offers personalized dietary recommendations.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PetType {
  DOG = 'Dog',
  CAT = 'Cat',
  BIRD = 'Bird',
  RABBIT = 'Rabbit',
  OTHER = 'Other'
}

export interface HealthMetric {
  date: string;
  weight: number;
  mood: string;
  activityLevel: number; // 1-10
}

export interface Vaccination {
  id: string;
  name: string;
  dueDate: string;
  completedDate?: string;
  isRequired: boolean;
}

export interface Pet {
  id: string;
  name: string;
  type: PetType;
  breed: string;
  birthDate: string;
  gender: 'Male' | 'Female';
  image?: string;
  metrics: HealthMetric[];
  vaccinations: Vaccination[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Pet, PetType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getBreedAdvice = async (pet: Pet): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide expert, concise care tips for a ${pet.breed} ${pet.type}. Include specific needs for diet, grooming, exercise, and common breed-specific health issues to watch out for.`,
    });
    return response.text || "I couldn't retrieve specific advice right now.";
  } catch (error) {
    console.error("Error fetching breed advice:", error);
    return "Error connecting to AI assistant.";
  }
};

export const getVaccinationSchedule = async (petType: PetType, breed: string, ageInMonths: number) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a recommended vaccination schedule for a ${breed} ${petType} that is currently ${ageInMonths} months old. Provide the response in JSON format.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              timeFrame: { type: Type.STRING, description: "When the vaccine should be administered (e.g., '8 weeks', 'Every 3 years')" },
              isRequired: { type: Type.BOOLEAN }
            },
            required: ["name", "timeFrame", "isRequired"]
          }
        }
      }
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Error fetching vaccination schedule:", error);
    return [];
  }
};

export const getDietaryRecommendation = async (pet: Pet): Promise<string> => {
  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const weightInfo = lastMetric ? `Current weight: ${lastMetric.weight}kg.` : "";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide dietary recommendations for a ${pet.breed} ${pet.type}. ${weightInfo} Focus on portion sizes, recommended nutrients, and foods to avoid. Keep it friendly and informative.`,
    });
    return response.text || "Dietary recommendations unavailable.";
  } catch (error) {
    console.error("Error fetching diet info:", error);
    return "Error connecting to AI assistant.";
  }
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  const contextPrompt = petContext 
    ? `You are PawPulse, an expert AI pet care assistant. You are talking to the owner of ${petContext.name}, a ${petContext.breed} ${petContext.type}. Be professional yet empathetic.`
    : "You are PawPulse, an expert AI pet care assistant. Help users with their pet-related questions.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: contextPrompt },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `User: ${message}` }
      ],
    });
    return response.text;
  } catch (error) {
    console.error("Chat error:", error);
    return "I'm having trouble thinking right now. Please try again in a moment.";
  }
};

import React from 'react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer 
} from 'recharts';
import { HealthMetric } from '../types';

interface HealthChartProps {
  data: HealthMetric[];
}

const HealthChart: React.FC<HealthChartProps> = ({ data }) => {
  if (!data || data.length === 0) {
    return (
      <div className="h-64 flex items-center justify-center bg-slate-100 rounded-xl text-slate-400">
        No health data yet. Log some metrics!
      </div>
    );
  }

  return (
    <div className="h-64 w-full">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
          <XAxis 
            dataKey="date" 
            tick={{ fontSize: 12, fill: '#64748b' }}
            axisLine={false}
            tickLine={false}
          />
          <YAxis 
            tick={{ fontSize: 12, fill: '#64748b' }}
            axisLine={false}
            tickLine={false}
          />
          <Tooltip 
            contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
          />
          <Line 
            type="monotone" 
            dataKey="weight" 
            stroke="#6366f1" 
            strokeWidth={3} 
            dot={{ r: 4, fill: '#6366f1' }}
            activeDot={{ r: 6 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export default HealthChart;

import React, { useState, useEffect } from 'react';
import { Pet, HealthMetric } from '../types';
import HealthChart from './HealthChart';
import { getBreedAdvice, getDietaryRecommendation } from '../services/geminiService';

interface DashboardProps {
  pet: Pet;
  onUpdatePet: (updatedPet: Pet) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ pet, onUpdatePet }) => {
  const [advice, setAdvice] = useState<string>('');
  const [diet, setDiet] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [newWeight, setNewWeight] = useState('');

  useEffect(() => {
    const fetchInfo = async () => {
      setLoading(true);
      const [breedAdvice, dietRec] = await Promise.all([
        getBreedAdvice(pet),
        getDietaryRecommendation(pet)
      ]);
      setAdvice(breedAdvice);
      setDiet(dietRec);
      setLoading(false);
    };
    fetchInfo();
  }, [pet.id]);

  const handleAddMetric = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWeight) return;

    const newMetric: HealthMetric = {
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      weight: parseFloat(newWeight),
      mood: 'Happy',
      activityLevel: 7
    };

    const updatedPet = {
      ...pet,
      metrics: [...pet.metrics, newMetric]
    };
    onUpdatePet(updatedPet);
    setNewWeight('');
  };

  const lastMetric = pet.metrics[pet.metrics.length - 1];

  return (
    <div className="space-y-6">
      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-weight-scale text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Current Weight</p>
              <h3 className="text-2xl font-bold text-slate-800">{lastMetric?.weight || '--'} kg</h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-rose-100 text-rose-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-syringe text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Next Vaccination</p>
              <h3 className="text-2xl font-bold text-slate-800">
                {pet.vaccinations.find(v => !v.completedDate)?.dueDate || 'None set'}
              </h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-cake-candles text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Breed</p>
              <h3 className="text-2xl font-bold text-slate-800">{pet.breed}</h3>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Weight Tracking Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Weight History</h3>
            <form onSubmit={handleAddMetric} className="flex gap-2">
              <input 
                type="number" 
                step="0.1"
                placeholder="New weight (kg)"
                value={newWeight}
                onChange={(e) => setNewWeight(e.target.value)}
                className="px-3 py-1.5 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none w-32"
              />
              <button className="bg-indigo-600 text-white p-1.5 rounded-lg hover:bg-indigo-700 transition-colors">
                <i className="fas fa-plus"></i>
              </button>
            </form>
          </div>
          <HealthChart data={pet.metrics} />
        </div>

        {/* Breed Specific Tips */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <i className="fas fa-lightbulb text-amber-500"></i>
            Expert Breed Advice
          </h3>
          {loading ? (
            <div className="animate-pulse space-y-3">
              <div className="h-4 bg-slate-100 rounded w-3/4"></div>
              <div className="h-4 bg-slate-100 rounded w-full"></div>
              <div className="h-4 bg-slate-100 rounded w-5/6"></div>
            </div>
          ) : (
            <div className="prose prose-slate max-w-none text-slate-600 text-sm leading-relaxed whitespace-pre-line">
              {advice}
            </div>
          )}
        </div>
      </div>

      {/* Dietary Advice Section */}
      <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-2xl text-white shadow-lg">
        <div className="flex flex-col md:flex-row gap-8 items-start">
          <div className="md:w-1/3">
            <h3 className="text-2xl font-bold mb-2">Dietary Guide</h3>
            <p className="text-indigo-100 text-sm">Personalized nutritional recommendations based on {pet.name}'s breed and activity level.</p>
            <div className="mt-6 p-4 bg-white/10 rounded-xl border border-white/20">
              <p className="text-xs uppercase font-bold text-indigo-200 mb-1">Top Recommendation</p>
              <p className="text-sm italic">"High protein intake is essential for muscle maintenance in {pet.breed} types."</p>
            </div>
          </div>
          <div className="md:w-2/3 bg-white/5 p-6 rounded-xl border border-white/10 flex-1 h-full">
            {loading ? (
              <div className="animate-pulse space-y-3">
                <div className="h-4 bg-white/10 rounded w-full"></div>
                <div className="h-4 bg-white/10 rounded w-5/6"></div>
                <div className="h-4 bg-white/10 rounded w-4/6"></div>
              </div>
            ) : (
              <div className="text-indigo-50 text-sm leading-relaxed whitespace-pre-line">
                {diet}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Pet, ChatMessage } from '../types';
import { chatWithAssistant } from '../services/geminiService';

interface AIChatProps {
  pet: Pet;
}

const AIChat: React.FC<AIChatProps> = ({ pet }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'assistant',
      content: `Hi! I'm PawPulse, your pet care assistant. How can I help you with ${pet.name} today?`,
      timestamp: Date.now()
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const history = messages.map(m => ({ role: m.role, content: m.content }));
    const response = await chatWithAssistant(history, input, pet);

    const assistantMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'assistant',
      content: response || "I'm sorry, I couldn't process that request.",
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, assistantMsg]);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-4 bg-indigo-600 text-white flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-indigo-400 flex items-center justify-center">
            <i className="fas fa-robot"></i>
          </div>
          <div>
            <h3 className="font-bold">PawPulse AI Assistant</h3>
            <p className="text-xs text-indigo-100 flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse"></span>
              Online & Ready to Help
            </p>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 p-6 overflow-y-auto space-y-4 bg-slate-50">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[80%] p-4 rounded-2xl ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-white text-slate-800 shadow-sm border border-slate-100 rounded-tl-none'
            }`}>
              <p className="text-sm leading-relaxed">{msg.content}</p>
              <p className={`text-[10px] mt-1 ${msg.role === 'user' ? 'text-indigo-200' : 'text-slate-400'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-slate-300 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-slate-300 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-slate-300 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-4 bg-white border-t border-slate-100 flex gap-2">
        <input 
          type="text"
          placeholder={`Ask about ${pet.name}'s care...`}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          className="flex-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
        />
        <button 
          disabled={isLoading}
          className="bg-indigo-600 text-white w-10 h-10 rounded-xl flex items-center justify-center hover:bg-indigo-700 transition-colors disabled:opacity-50"
        >
          <i className="fas fa-paper-plane"></i>
        </button>
      </form>
    </div>
  );
};

export default AIChat;

