  gender: 'Female',
  metrics: [
    { date: 'Oct 12', weight: 28.5, mood: 'Happy', activityLevel: 8 },
    { date: 'Nov 15', weight: 29.2, mood: 'Active', activityLevel: 7 },
    { date: 'Dec 10', weight: 29.8, mood: 'Hungry', activityLevel: 9 },
    { date: 'Jan 05', weight: 30.1, mood: 'Calm', activityLevel: 6 },
