                    <div>
                      <h4 className="font-bold text-slate-800 flex items-center gap-2">
                        {v.name}
                        {v.isRequired && <span className="text-[10px] bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded font-normal uppercase tracking-wider">Required</span>}
                      </h4>
                      <p className="text-sm text-slate-500">
                        {v.completedDate ? `Completed on ${v.completedDate}` : `Due by ${v.dueDate}`}
                      </p>
                    </div>
                  </div>
                  <button 
                    onClick={() => toggleVaccine(v.id)}
                    className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                      v.completedDate 
                        ? 'text-slate-400 hover:text-rose-500' 
                        : 'bg-slate-800 text-white hover:bg-indigo-600'
                    }`}
                  >
                    {v.completedDate ? 'Mark Incomplete' : 'Log as Completed'}
                  </button>
                </div>
              ))}
            </div>
            <div className="p-6 bg-slate-50 border-t border-slate-100">
              <div className="flex items-start gap-4 p-4 bg-amber-50 rounded-xl border border-amber-100">
                <i className="fas fa-circle-info text-amber-500 mt-1"></i>
                <div className="text-sm text-amber-800">
                  <p className="font-bold mb-1">Upcoming Milestone</p>
                  <p>Luna is due for her Rabies booster in June. We'll remind you 2 weeks before the deadline!</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Pet, PetType, Vaccination } from './types';
import Dashboard from './components/Dashboard';
import AIChat from './components/AIChat';
import Login from './components/Login';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'chat' | 'vaccines'>('dashboard');
  const [pet, setPet] = useState<Pet | null>(() => {
    const saved = localStorage.getItem('pawpulse_pet');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (pet) {
      localStorage.setItem('pawpulse_pet', JSON.stringify(pet));
    }
  }, [pet]);

  const handleLogin = (petData: any) => {
    // When logging in, we initialize the pet with the provided data and some default empty states
    const newPet: Pet = {
      id: Math.random().toString(36).substr(2, 9),
      name: petData.name,
      type: PetType.DOG, // Default to Dog, can be changed later
      breed: 'Golden Retriever', // Default breed to show some initial data
      birthDate: new Date().toISOString().split('T')[0],
      gender: 'Male',
      metrics: [],
      vaccinations: [
        { id: 'v1', name: 'Rabies', dueDate: '2024-12-15', isRequired: true },
        { id: 'v2', name: 'DHPP', dueDate: '2024-11-10', isRequired: true },
      ]
    };
    setPet(newPet);
  };

  const handleUpdatePet = (updatedPet: Pet) => {
    setPet(updatedPet);
  };

  const toggleVaccine = (id: string) => {
    if (!pet) return;
    const updatedVaccinations = pet.vaccinations.map(v => 
      v.id === id 
        ? { ...v, completedDate: v.completedDate ? undefined : new Date().toISOString().split('T')[0] } 
        : v
    );
    setPet({ ...pet, vaccinations: updatedVaccinations });
  };

  const handleLogout = () => {
    localStorage.removeItem('pawpulse_pet');
    setPet(null);
  };

  if (!pet) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row animate-in fade-in duration-700">
      {/* Sidebar Navigation */}
      <nav className="w-full md:w-64 bg-white border-r border-slate-200 p-6 flex flex-col gap-8 md:fixed md:h-screen">
