            <p className="text-slate-500 text-sm mt-1">
              {activeTab === 'dashboard' ? `Welcome back! Here's ${pet.name}'s latest vitals.` : 
               activeTab === 'chat' ? `Ask me anything about ${pet.name}'s health, diet, or behavior.` : 
               'Keep track of upcoming shots and medical records.'}
