              <i className="fas fa-bell"></i>
              Notifications
            </button>
            <button className="bg-indigo-600 px-4 py-2 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 transition-colors shadow-md flex items-center gap-2">
              <i className="fas fa-plus"></i>
