                {pet.vaccinations.filter(v => v.completedDate).length}/{pet.vaccinations.length} Completed
              </span>
            </div>
            <div className="divide-y divide-slate-100">
              {pet.vaccinations.length > 0 ? pet.vaccinations.map((v) => (
                <div key={v.id} className="p-6 flex items-center justify-between hover:bg-slate-50 transition-colors group">
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center transition-colors ${
                      v.completedDate ? 'bg-green-100 text-green-600' : 'bg-rose-100 text-rose-600'
                    }`}>
                      <i className={`fas ${v.completedDate ? 'fa-check-circle' : 'fa-clock'} text-xl`}></i>
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-800 flex items-center gap-2">
                        {v.name}
                        {v.isRequired && <span className="text-[10px] bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded font-normal uppercase tracking-wider">Required</span>}
                      </h4>
                      <p className="text-sm text-slate-500">
                        {v.completedDate ? `Completed on ${v.completedDate}` : `Due by ${v.dueDate}`}
                      </p>
                    </div>
                  </div>
                  <button 
                    onClick={() => toggleVaccine(v.id)}
                    className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                      v.completedDate 
                        ? 'text-slate-400 hover:text-rose-500' 
                        : 'bg-slate-800 text-white hover:bg-indigo-600'
                    }`}
                  >
                    {v.completedDate ? 'Mark Incomplete' : 'Log as Completed'}
                  </button>
                </div>
              )) : (
                <div className="p-10 text-center text-slate-400">
                  <i className="fas fa-syringe text-3xl mb-2 block opacity-20"></i>
