  onUpdate: (updatedPet: Pet) => void;
  onComplete: () => void;
}

const PET_TYPES = [
  { type: PetType.DOG, icon: 'fa-dog', color: 'bg-amber-100 text-amber-600', label: 'Dog' },
  { type: PetType.CAT, icon: 'fa-cat', color: 'bg-rose-100 text-rose-600', label: 'Cat' },
  { type: PetType.BIRD, icon: 'fa-dove', color: 'bg-blue-100 text-blue-600', label: 'Bird' },
  { type: PetType.RABBIT, icon: 'fa-rabbit', color: 'bg-emerald-100 text-emerald-600', label: 'Rabbit' },
  { type: PetType.HAMSTER, icon: 'fa-cheese', color: 'bg-orange-100 text-orange-600', label: 'Hamster' },
  { type: PetType.FISH, icon: 'fa-fish', color: 'bg-cyan-100 text-cyan-600', label: 'Fish' },
];

const DOG_BREEDS = [
  'Golden Retriever', 'Labrador', 'German Shepherd', 'Poodle', 
  'French Bulldog', 'Beagle', 'Rottweiler', 'Dachshund', 
  'Siberian Husky', 'Boxer', 'Chihuahua', 'Shih Tzu'
];

const CAT_BREEDS = [
  'Persian', 'Maine Coon', 'Siamese', 'Ragdoll', 
  'Bengal', 'Abyssinian', 'Sphynx', 'British Shorthair'
];

const PetSetup: React.FC<PetSetupProps> = ({ pet, onUpdate, onComplete }) => {
  const [selectedType, setSelectedType] = useState<PetType | null>(null);
  const [selectedBreed, setSelectedBreed] = useState<string>('');

  const handleSave = () => {
    if (!selectedType) return;
    onUpdate({
      ...pet,
      type: selectedType,
      breed: selectedBreed || 'Standard'
    });
    onComplete();
  };

  return (
    <div className="max-w-4xl mx-auto py-8 px-4">
