                  </button>
                ))}
              </div>

              <div className="mt-4">
                <p className="text-xs text-slate-400 mb-2">Can't find the breed? Type it below:</p>
                <input 
                  type="text"
                  placeholder="Enter custom breed..."
                  value={selectedBreed}
