                  className="w-full max-w-sm px-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-xl focus:ring-0 focus:border-indigo-500 outline-none transition-all"
                />
              </div>
            </div>
          )}

          <div className="pt-8 border-t border-slate-100 flex justify-end">
            <button
              disabled={!selectedType}
              onClick={handleSave}
              className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-bold text-lg hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 disabled:opacity-50 disabled:shadow-none flex items-center gap-2 group"
            >
              Continue to Dashboard
              <i className="fas fa-chevron-right text-sm group-hover:translate-x-1 transition-transform"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

