  const handleLogin = (petData: any) => {
    const newPet: Pet = {
      id: Math.random().toString(36).substr(2, 9),
      name: petData.name,
      type: PetType.OTHER,
      breed: 'Unknown',
      birthDate: new Date().toISOString().split('T')[0],
      gender: 'Male',
      metrics: [],
      vaccinations: []
    };
    setPet(newPet);
    setActiveTab('setup');
