                <button
                  key={item.type}
                  onClick={() => {
                    setSelectedType(item.type);
                    setSelectedBreed('');
                  }}
                  className={`flex flex-col items-center p-6 rounded-[2rem] border-2 transition-all group ${
                    selectedType === item.type 
                      ? 'border-indigo-600 bg-indigo-50 shadow-md scale-105' 
                      : 'border-slate-100 hover:border-indigo-200 bg-slate-50'
                  }`}
                >
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-3 transition-transform group-hover:scale-110 ${item.color}`}>
