                  <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                  <p className="text-indigo-600 font-bold">Analyzing breed with AI...</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                  {breeds.map((breed) => (
                    <button
                      key={breed.name}
                      onClick={() => setSelectedBreed(breed.name)}
                      className={`group relative flex flex-col items-center rounded-2xl overflow-hidden border-4 transition-all ${
                        selectedBreed === breed.name
                          ? 'border-indigo-600 ring-4 ring-indigo-50'
                          : 'border-white hover:border-slate-200 shadow-sm'
                      }`}
                    >
                      <div className="aspect-square w-full overflow-hidden">
                        <img 
                          src={breed.image} 
                          alt={breed.name} 
                          className={`w-full h-full object-cover transition-transform duration-500 ${
                            selectedBreed === breed.name ? 'scale-110' : 'group-hover:scale-105'
                          }`} 
                        />
                      </div>
                      <div className={`absolute bottom-0 inset-x-0 p-2 text-center transition-colors ${
                        selectedBreed === breed.name ? 'bg-indigo-600 text-white' : 'bg-black/50 backdrop-blur-sm text-white'
                      }`}>
                        <span className="text-xs font-bold truncate block">{breed.name}</span>
                      </div>
                    </button>
                  ))}
                </div>
              )}

              <div className="mt-8 p-6 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                <p className="text-sm font-bold text-slate-600 mb-3">Don't see your breed? Add it manually:</p>
                <div className="flex gap-2">
                  <input 
                    type="text"
                    placeholder="Enter breed name..."
                    value={selectedBreed}
                    onChange={(e) => setSelectedBreed(e.target.value)}
                    className="flex-1 px-4 py-3 bg-white border-2 border-slate-200 rounded-xl focus:ring-0 focus:border-indigo-500 outline-none transition-all shadow-sm"
                  />
                </div>
              </div>
            </div>
          )}

          <div className="pt-8 border-t border-slate-100 flex justify-end">
            <button
              disabled={!selectedType || !selectedBreed}
              onClick={handleSave}
              className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-bold text-lg hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 disabled:opacity-50 disabled:shadow-none flex items-center gap-2 group"
            >
              Finish Setup
              <i className="fas fa-check-circle group-hover:scale-110 transition-transform"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

