const PetSetup: React.FC<PetSetupProps> = ({ pet, onUpdate, onComplete }) => {
  const [selectedType, setSelectedType] = useState<PetType | null>(null);
  const [selectedBreed, setSelectedBreed] = useState<string>('');
  const [isIdentifying, setIsIdentifying] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    if (!selectedType) return;
    onUpdate({
      ...pet,
      type: selectedType,
      breed: selectedBreed || 'Standard'
    });
    onComplete();
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsIdentifying(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64Image = reader.result as string;
      const breed = await identifyBreedFromImage(base64Image);
      setSelectedBreed(breed);
      setIsIdentifying(false);
    };
    reader.readAsDataURL(file);
  };

  const breeds = selectedType ? BREED_DATA[selectedType] || [{ name: 'Standard', image: 'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?auto=format&fit=crop&w=400&q=80' }] : [];

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <div className="bg-white rounded-[3rem] shadow-xl border border-slate-100 overflow-hidden">
        {/* Header Section */}
        <div className="bg-gradient-to-r from-indigo-600 to-indigo-800 p-10 text-center text-white">
          <h2 className="text-4xl font-black mb-3">Welcome, {pet.name}!</h2>
          <p className="text-indigo-100 text-lg opacity-90 max-w-2xl mx-auto">
            Let's customize your experience by selecting {pet.name}'s specific details.
          </p>
        </div>

        <div className="p-8 md:p-12 space-y-16">
          {/* Step 1: Select Type */}
          <section>
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">
                <span className="w-10 h-10 rounded-2xl bg-indigo-600 text-white flex items-center justify-center text-lg shadow-lg shadow-indigo-200">1</span>
                What kind of pet?
              </h3>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-6">
              {PET_TYPES.map((item) => (
                <button
                  key={item.type}
                  onClick={() => {
                    setSelectedType(item.type);
                    setSelectedBreed('');
                  }}
                  className={`flex flex-col items-center p-6 rounded-[2.5rem] border-4 transition-all duration-300 group ${
                    selectedType === item.type 
                      ? 'border-indigo-600 bg-indigo-50/50 shadow-xl scale-105' 
                      : 'border-slate-50 hover:border-indigo-200 bg-slate-50'
                  }`}
                >
                  <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center mb-4 transition-all duration-500 group-hover:rotate-12 ${item.color} shadow-sm`}>
                    <i className={`fas ${item.icon} text-2xl`}></i>
                  </div>
                  <span className={`text-sm font-black tracking-wide uppercase ${selectedType === item.type ? 'text-indigo-600' : 'text-slate-500'}`}>
                    {item.label}
                  </span>
                </button>
              ))}
            </div>
          </section>

          {/* Step 2: Select Breed Carousel */}
          {selectedType && (
            <section className="animate-in fade-in slide-in-from-bottom-8 duration-700">
              <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6 mb-10">
                <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">
                  <span className="w-10 h-10 rounded-2xl bg-indigo-600 text-white flex items-center justify-center text-lg shadow-lg shadow-indigo-200">2</span>
                  Select the Breed
                </h3>

                {/* AI Identification Prompt */}
                <div className="bg-indigo-50 border border-indigo-100 rounded-[2rem] p-2 flex items-center gap-4 w-full md:w-auto shadow-inner">
                  <span className="text-sm font-bold text-indigo-700 ml-4 hidden sm:inline">Don't know the breed?</span>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white rounded-[1.5rem] text-sm font-black hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 active:scale-95 flex-1 md:flex-none"
                  >
                    <i className="fas fa-magic"></i>
                    AI Identify via Photo
                  </button>
                  <input 
                    type="file" 
                    accept="image/*" 
                    ref={fileInputRef} 
                    className="hidden" 
                    onChange={handleFileUpload}
                  />
                </div>
              </div>

              {isIdentifying ? (
                <div className="py-20 flex flex-col items-center justify-center bg-slate-50 rounded-[3rem] border-4 border-dashed border-slate-200">
                  <div className="relative">
                    <div className="w-16 h-16 border-4 border-indigo-600/20 rounded-full"></div>
                    <div className="absolute top-0 left-0 w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                  </div>
                  <p className="mt-6 text-indigo-600 font-black text-lg animate-pulse tracking-tight">AI is analyzing the breed...</p>
                </div>
              ) : (
                <div className="relative group">
                  {/* Breed Carousel */}
                  <div className="flex overflow-x-auto gap-6 pb-8 px-2 snap-x no-scrollbar">
                    {breeds.map((breed) => (
                      <button
                        key={breed.name}
                        onClick={() => setSelectedBreed(breed.name)}
                        className={`snap-center flex-shrink-0 w-64 group relative flex flex-col items-center rounded-[2.5rem] overflow-hidden border-4 transition-all duration-500 ${
                          selectedBreed === breed.name
                            ? 'border-indigo-600 ring-8 ring-indigo-50 shadow-2xl'
                            : 'border-white hover:border-indigo-100 shadow-lg bg-white'
                        }`}
                      >
                        <div className="aspect-[4/5] w-full overflow-hidden">
                          <img 
                            src={breed.image} 
                            alt={breed.name} 
                            className={`w-full h-full object-cover transition-transform duration-1000 ${
                              selectedBreed === breed.name ? 'scale-110' : 'group-hover:scale-105'
                            }`} 
                          />
                        </div>
                        <div className={`absolute bottom-0 inset-x-0 p-5 text-center transition-all duration-500 ${
                          selectedBreed === breed.name ? 'bg-indigo-600 text-white' : 'bg-black/40 backdrop-blur-md text-white'
                        }`}>
                          <span className="text-sm font-black tracking-wider uppercase block">{breed.name}</span>
                          {selectedBreed === breed.name && (
                            <i className="fas fa-check-circle mt-1 text-indigo-200"></i>
                          )}
                        </div>
                      </button>
                    ))}

                    {/* Add Custom Breed Button at end of carousel */}
                    <div className="snap-center flex-shrink-0 w-64 flex flex-col items-center justify-center p-8 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-slate-200 text-center">
                        <div className="w-16 h-16 rounded-full bg-slate-200 text-slate-500 flex items-center justify-center mb-4">
                            <i className="fas fa-plus text-2xl"></i>
                        </div>
                        <p className="text-sm font-bold text-slate-500">Other Breed?</p>
                        <input 
                            type="text"
                            placeholder="Type breed here..."
                            value={selectedBreed && !breeds.find(b => b.name === selectedBreed) ? selectedBreed : ''}
                            onChange={(e) => setSelectedBreed(e.target.value)}
                            className="mt-4 w-full px-4 py-3 bg-white border-2 border-slate-200 rounded-xl focus:ring-0 focus:border-indigo-500 outline-none transition-all text-sm font-bold text-slate-700"
                        />
                    </div>
                  </div>

                  {/* Scroll indicators */}
                  <div className="absolute top-1/2 -left-4 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <div className="w-10 h-10 bg-white shadow-lg rounded-full flex items-center justify-center text-slate-400 border border-slate-100">
                          <i className="fas fa-chevron-left"></i>
                      </div>
                  </div>
                  <div className="absolute top-1/2 -right-4 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <div className="w-10 h-10 bg-white shadow-lg rounded-full flex items-center justify-center text-slate-400 border border-slate-100">
                          <i className="fas fa-chevron-right"></i>
                      </div>
                  </div>
                </div>
              )}
            </section>
          )}

          {/* Footer Navigation */}
          <div className="pt-10 border-t border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="text-slate-400 text-sm font-medium flex items-center gap-2">
                <i className="fas fa-shield-halved"></i>
                We use secure AI to provide breed-specific health guides.
            </div>
            <button
              disabled={!selectedType || !selectedBreed}
              onClick={handleSave}
              className="w-full md:w-auto px-12 py-5 bg-indigo-600 text-white rounded-[2rem] font-black text-xl hover:bg-indigo-700 transition-all shadow-2xl shadow-indigo-100 disabled:opacity-40 disabled:shadow-none flex items-center justify-center gap-4 group active:scale-95"
            >
              Start My Journey
              <i className="fas fa-arrow-right group-hover:translate-x-2 transition-transform"></i>
            </button>
          </div>
        </div>
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

