// Sub-component for handling image loading states and errors
const BreedImage: React.FC<{ src: string; alt: string; isSelected: boolean }> = ({ src, alt, isSelected }) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  return (
    <div className="relative w-full h-full bg-slate-100 overflow-hidden">
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-slate-100 animate-pulse">
          <i className="fas fa-paw text-slate-300 text-4xl"></i>
        </div>
      )}

      {error ? (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-200 text-slate-400">
          <i className="fas fa-image-slash text-3xl mb-2"></i>
          <span className="text-[10px] font-bold px-2 text-center uppercase">Image Unavailable</span>
        </div>
      ) : (
        <img
          src={src}
          alt={alt}
          onLoad={() => setLoading(false)}
          onError={() => {
            setLoading(false);
            setError(true);
          }}
          className={`w-full h-full object-cover transition-all duration-1000 ${
            isSelected ? 'scale-110 saturate-100' : 'saturate-[0.85] group-hover:scale-110 group-hover:saturate-100'
          } ${loading ? 'opacity-0' : 'opacity-100'}`}
        />
      )}
    </div>
  );
};

