// Optimized sub-component for handling image loading states and reliable fallbacks
const BreedImage: React.FC<{ src: string; alt: string; isSelected: boolean }> = ({ src, alt, isSelected }) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  // High-reliability fallback images based on common keywords
  const getFallback = () => {
    if (alt.toLowerCase().includes('dog')) return 'https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&q=60&w=400';
    if (alt.toLowerCase().includes('cat')) return 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?auto=format&fit=crop&q=60&w=400';
    if (alt.toLowerCase().includes('bird')) return 'https://images.unsplash.com/photo-1522913423274-974e548ef86e?auto=format&fit=crop&q=60&w=400';
    if (alt.toLowerCase().includes('fish')) return 'https://images.unsplash.com/photo-1522069169874-c58ec4b76be5?auto=format&fit=crop&q=60&w=400';
    return 'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?auto=format&fit=crop&q=60&w=400';
  };

  return (
    <div className="relative w-full h-full bg-slate-100 overflow-hidden">
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-slate-100">
          <div className="w-8 h-8 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
        </div>
      )}

      <img
        src={error ? getFallback() : src}
        alt={alt}
        onLoad={() => setLoading(false)}
        onError={() => {
          if (!error) {
            setError(true);
          } else {
            setLoading(false);
          }
        }}
        className={`w-full h-full object-cover transition-all duration-700 ${
          isSelected ? 'scale-110 saturate-100' : 'saturate-[0.85] group-hover:scale-110 group-hover:saturate-100'
        } ${loading ? 'opacity-0' : 'opacity-100'}`}
      />

      {error && !loading && (
        <div className="absolute top-2 right-2">
          <span className="bg-amber-500/80 backdrop-blur-sm text-[8px] text-white px-1.5 py-0.5 rounded-full font-bold uppercase tracking-widest">Fallback</span>
        </div>
      )}
    </div>
  );
};

