  const carouselRef = useRef<HTMLDivElement>(null);

  const handleSave = () => {
    if (!selectedType) return;
    onUpdate({
      ...pet,
      type: selectedType,
      breed: selectedBreed || 'Standard'
    });
    onComplete();
