            <i className="fas fa-paw text-xl"></i>
          </div>
          <span className="text-xl font-bold tracking-tight">PawPulse <span className="text-slate-400 font-light">AI</span></span>
        </div>

        {!isNeedsSetup && (
          <div className="flex-1 flex flex-col gap-1">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === 'dashboard' ? 'bg-indigo-50 text-indigo-600 font-semibold' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <i className="fas fa-columns w-5"></i>
              Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('chat')}
              className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === 'chat' ? 'bg-indigo-50 text-indigo-600 font-semibold' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <i className="fas fa-comment-dots w-5"></i>
              AI Assistant
            </button>
            <button 
              onClick={() => setActiveTab('vaccines')}
              className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === 'vaccines' ? 'bg-indigo-50 text-indigo-600 font-semibold' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <i className="fas fa-calendar-check w-5"></i>
              Vaccinations
