            <button 
              onClick={() => setActiveTab('setup')}
              className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === 'setup' ? 'bg-indigo-50 text-indigo-600 font-semibold' : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <i className="fas fa-paw w-5"></i>
              Pet Profile
