                const daysLeft = calculateDaysLeft(v.dueDate);
                const isOverdue = daysLeft < 0 && !v.completedDate;

                return (
                  <div key={v.id} className="p-6 flex items-center justify-between hover:bg-slate-50 transition-colors group">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-xl flex items-center justify-center transition-colors ${
                        v.completedDate ? 'bg-green-100 text-green-600' : 
                        isOverdue ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'
