  const nextVaccine = pet.vaccinations
    .filter(v => !v.completedDate)
    .sort((a, b) => {
      const dateA = a.dueDate.split('.').reverse().join('-');
      const dateB = b.dueDate.split('.').reverse().join('-');
      return dateA.localeCompare(dateB);
