import { GoogleGenAI, Type } from "@google/genai";
import { Pet, PetType, DailyDietPlan } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  try {
    const imagePart = {
      inlineData: {
        mimeType: 'image/jpeg',
        data: base64Image.split(',')[1], // Remove the data:image/jpeg;base64, prefix
      },
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          imagePart, 
          { text: "Identify the specific breed of the pet in this image. Return ONLY the breed name as a plain string (e.g., 'Golden Retriever'). If you are unsure, provide your best guess." }
        ] 
      },
    });

    return response.text?.trim() || "Unknown Breed";
  } catch (error) {
    console.error("Error identifying breed:", error);
    return "Identification Failed";
  }
};

export const getBreedAdvice = async (pet: Pet): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide expert, concise care tips for a ${pet.breed} ${pet.type}. Include specific needs for diet, grooming, exercise, and common breed-specific health issues to watch out for.`,
    });
    return response.text || "I couldn't retrieve specific advice right now.";
  } catch (error) {
    console.error("Error fetching breed advice:", error);
    return "Error connecting to AI assistant.";
  }
};

export const getStructuredDietPlan = async (pet: Pet): Promise<DailyDietPlan | null> => {
  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const weightInfo = lastMetric ? `Weight: ${lastMetric.weight}kg.` : "";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a structured daily diet plan for a ${pet.breed} ${pet.type}. ${weightInfo} Provide meal times (e.g. 08:00 AM), quantities, and specific food types. Output as JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            meals: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  time: { type: Type.STRING },
                  label: { type: Type.STRING, description: "e.g. Breakfast, Lunch, Dinner, Snack" },
                  quantity: { type: Type.STRING },
                  notes: { type: Type.STRING }
                },
                required: ["time", "label", "quantity", "notes"]
              }
            },
            waterIntake: { type: Type.STRING },
            totalCalories: { type: Type.STRING }
          },
          required: ["meals", "waterIntake"]
        }
      }
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Error fetching structured diet plan:", error);
    return null;
  }
};

export const getDietaryRecommendation = async (pet: Pet): Promise<string> => {
  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const weightInfo = lastMetric ? `Current weight: ${lastMetric.weight}kg.` : "";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide dietary recommendations for a ${pet.breed} ${pet.type}. ${weightInfo} Focus on portion sizes, recommended nutrients, and foods to avoid. Keep it friendly and informative.`,
    });
    return response.text || "Dietary recommendations unavailable.";
  } catch (error) {
    console.error("Error fetching diet info:", error);
    return "Error connecting to AI assistant.";
  }
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  const contextPrompt = petContext 
    ? `You are PawPulse, an expert AI pet care assistant. You are talking to the owner of ${petContext.name}, a ${petContext.breed} ${petContext.type}. Be professional yet empathetic.`
    : "You are PawPulse, an expert AI pet care assistant. Help users with their pet-related questions.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: contextPrompt },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `User: ${message}` }
      ],
    });
    return response.text;
  } catch (error) {
    console.error("Chat error:", error);
    return "I'm having trouble thinking right now. Please try again in a moment.";
  }
};

import React, { useState, useEffect } from 'react';
import { Pet, HealthMetric, DailyDietPlan } from '../types';
import HealthChart from './HealthChart';
import { getBreedAdvice, getDietaryRecommendation, getStructuredDietPlan } from '../services/geminiService';

interface DashboardProps {
  pet: Pet;
  onUpdatePet: (updatedPet: Pet) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ pet, onUpdatePet }) => {
  const [advice, setAdvice] = useState<string>('');
  const [diet, setDiet] = useState<string>('');
  const [structuredDiet, setStructuredDiet] = useState<DailyDietPlan | null>(pet.dietPlan || null);
  const [loading, setLoading] = useState(true);
  const [newWeight, setNewWeight] = useState('');

  useEffect(() => {
    const fetchInfo = async () => {
      setLoading(true);
      const [breedAdvice, dietRec, dietPlan] = await Promise.all([
        getBreedAdvice(pet),
        getDietaryRecommendation(pet),
        !pet.dietPlan ? getStructuredDietPlan(pet) : Promise.resolve(pet.dietPlan)
      ]);
      setAdvice(breedAdvice);
      setDiet(dietRec);
      if (dietPlan && !pet.dietPlan) {
        setStructuredDiet(dietPlan);
        onUpdatePet({ ...pet, dietPlan });
      } else if (pet.dietPlan) {
        setStructuredDiet(pet.dietPlan);
      }
      setLoading(false);
    };
    fetchInfo();
  }, [pet.id]);

  const handleAddMetric = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWeight) return;

    const newMetric: HealthMetric = {
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      weight: parseFloat(newWeight),
      mood: 'Happy',
      activityLevel: 7
    };

    const updatedPet = {
      ...pet,
      metrics: [...pet.metrics, newMetric]
    };
    onUpdatePet(updatedPet);
    setNewWeight('');
  };

  const calculateDaysLeft = (dueDate: string) => {
    const [day, month, year] = dueDate.split('.');
    const due = new Date(`${year}-${month}-${day}`);
    const now = new Date();
    const diffTime = due.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const nextVaccine = pet.vaccinations
    .filter(v => !v.completedDate)
    .sort((a, b) => {
      const dateA = a.dueDate.split('.').reverse().join('-');
      const dateB = b.dueDate.split('.').reverse().join('-');
      return dateA.localeCompare(dateB);
    })[0];

  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const daysLeft = nextVaccine ? calculateDaysLeft(nextVaccine.dueDate) : null;

  return (
    <div className="space-y-6 pb-12">
      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-weight-scale text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Current Weight</p>
              <h3 className="text-2xl font-bold text-slate-800">{lastMetric?.weight || '--'} kg</h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${daysLeft !== null && daysLeft < 7 ? 'bg-rose-100 text-rose-600' : 'bg-indigo-100 text-indigo-600'}`}>
              <i className="fas fa-syringe text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Next Vaccination</p>
              <h3 className="text-xl font-bold text-slate-800">
                {nextVaccine ? (
                  <div className="flex flex-col">
                    <span>{nextVaccine.dueDate}</span>
                    <span className={`text-xs font-bold ${daysLeft !== null && daysLeft < 7 ? 'text-rose-500' : 'text-indigo-500'}`}>
                      {daysLeft !== null ? (daysLeft < 0 ? 'Overdue!' : `${daysLeft} days remaining`) : ''}
                    </span>
                  </div>
                ) : 'None scheduled'}
              </h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-paw text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Breed</p>
              <h3 className="text-2xl font-bold text-slate-800">{pet.breed}</h3>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Diet Plan - NEW SECTION */}
      <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">Daily Diet Plan</h3>
            <p className="text-slate-500 text-sm">Time-specific meal schedule for {pet.name}</p>
          </div>
          <div className="flex gap-4">
            <div className="bg-blue-50 px-4 py-2 rounded-xl border border-blue-100 flex items-center gap-2">
              <i className="fas fa-droplet text-blue-500"></i>
              <span className="text-xs font-bold text-blue-700">{structuredDiet?.waterIntake || '800ml/day'}</span>
            </div>
            {structuredDiet?.totalCalories && (
              <div className="bg-emerald-50 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                <i className="fas fa-bolt text-emerald-500"></i>
                <span className="text-xs font-bold text-emerald-700">{structuredDiet.totalCalories}</span>
              </div>
            )}
          </div>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[1, 2, 3, 4].map(i => (
              <div key={i} className="h-32 bg-slate-50 rounded-2xl animate-pulse"></div>
            ))}
          </div>
        ) : structuredDiet ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
            {structuredDiet.meals.map((meal, idx) => (
              <div key={idx} className="bg-slate-50 border border-slate-100 p-6 rounded-3xl group hover:border-indigo-200 transition-all hover:shadow-lg hover:shadow-indigo-50/50">
                <div className="flex justify-between items-start mb-4">
                  <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-1 rounded-md">
                    {meal.time}
                  </span>
                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center text-slate-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                    <i className={`fas ${
                      meal.label.toLowerCase().includes('breakfast') ? 'fa-sun' : 
                      meal.label.toLowerCase().includes('lunch') ? 'fa-cloud-sun' : 
                      meal.label.toLowerCase().includes('dinner') ? 'fa-moon' : 'fa-cookie-bite'
                    }`}></i>
                  </div>
                </div>
                <h4 className="font-bold text-slate-800 mb-1">{meal.label}</h4>
                <p className="text-sm font-black text-indigo-500 mb-2">{meal.quantity}</p>
                <p className="text-xs text-slate-500 leading-relaxed italic">{meal.notes}</p>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-10 text-slate-400">
            <i className="fas fa-utensils text-3xl mb-2 opacity-20"></i>
            <p>No diet plan generated yet.</p>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Weight Tracking Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Weight History</h3>
            <form onSubmit={handleAddMetric} className="flex gap-2">
              <input 
                type="number" 
                step="0.1"
                placeholder="New weight (kg)"
                value={newWeight}
                onChange={(e) => setNewWeight(e.target.value)}
                className="px-3 py-1.5 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none w-32"
              />
              <button className="bg-indigo-600 text-white p-1.5 rounded-lg hover:bg-indigo-700 transition-colors">
                <i className="fas fa-plus"></i>
              </button>
            </form>
          </div>
          <HealthChart data={pet.metrics} />
        </div>

        {/* Breed Specific Tips */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <i className="fas fa-lightbulb text-amber-500"></i>
            Expert Breed Advice
          </h3>
          {loading ? (
            <div className="animate-pulse space-y-3">
              <div className="h-4 bg-slate-100 rounded w-3/4"></div>
              <div className="h-4 bg-slate-100 rounded w-full"></div>
              <div className="h-4 bg-slate-100 rounded w-5/6"></div>
