const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'chat' | 'vaccines' | 'setup'>('dashboard');
  const [pet, setPet] = useState<Pet | null>(() => {
    const saved = localStorage.getItem('pawpulse_pet');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    if (pet) {
      localStorage.setItem('pawpulse_pet', JSON.stringify(pet));
    }
  }, [pet]);

  const calculateDaysLeft = (dueDate: string) => {
    const [day, month, year] = dueDate.split('.');
    const due = new Date(`${year}-${month}-${day}`);
    const now = new Date();
    const diffTime = due.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const handleLogin = (petData: any) => {
    const newPet: Pet = {
      id: Math.random().toString(36).substr(2, 9),
      name: petData.name,
      type: PetType.OTHER,
      breed: 'Unknown',
      birthDate: new Date().toISOString().split('T')[0],
      gender: 'Male',
      metrics: [],
      vaccinations: [] // Will be populated in PetSetup based on species
    };
    setPet(newPet);
    setActiveTab('setup');
  };

  const handleUpdatePet = (updatedPet: Pet) => {
    setPet(updatedPet);
  };

  const toggleVaccine = (id: string) => {
    if (!pet) return;
    const updatedVaccinations = pet.vaccinations.map(v => 
      v.id === id 
        ? { ...v, completedDate: v.completedDate ? undefined : new Date().toLocaleDateString('en-GB').replace(/\//g, '.') } 
        : v
    );
    setPet({ ...pet, vaccinations: updatedVaccinations });
  };

  const handleLogout = () => {
    localStorage.removeItem('pawpulse_pet');
    setPet(null);
    setActiveTab('dashboard');
  };

  if (!pet) {
    return <Login onLogin={handleLogin} />;
  }

  const isNeedsSetup = pet.breed === 'Unknown';
  const currentTab = isNeedsSetup ? 'setup' : activeTab;

  return (
    <div className="min-h-screen flex flex-col md:flex-row animate-in fade-in duration-700">
