const PetSetup: React.FC<PetSetupProps> = ({ pet, onUpdate, onComplete }) => {
  const [selectedType, setSelectedType] = useState<PetType | null>(null);
  const [selectedBreed, setSelectedBreed] = useState<string>('');
  const [isIdentifying, setIsIdentifying] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [setupStep, setSetupStep] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const carouselRef = useRef<HTMLDivElement>(null);

  const handleSave = async () => {
    if (!selectedType || !selectedBreed) return;
    setIsProcessing(true);

    const tempPet: Pet = {
      ...pet,
      type: selectedType,
      breed: selectedBreed
    };

    try {
      // Fetching all data SEQUENTIALLY to avoid burst 429 errors
      setSetupStep('Customizing vaccination schedule...');
      const vaccines = await getRecommendedVaccinations(tempPet, ['23.04.2026', '22.05.2026']);

      setSetupStep('Designing dietary blueprint...');
      const dietPlan = await getStructuredDietPlan(tempPet);

      setSetupStep('Gathering breed-specific care tips...');
      const breedAdvice = await getBreedAdvice(tempPet);

      setSetupStep('Finalizing nutritional recommendations...');
      const dietRec = await getDietaryRecommendation(tempPet);

      onUpdate({
        ...tempPet,
        vaccinations: vaccines.length > 0 ? vaccines : pet.vaccinations,
        dietPlan: dietPlan || pet.dietPlan,
        breedAdvice: breedAdvice || undefined,
        dietaryRecommendation: dietRec || undefined
      });

      setIsProcessing(false);
      onComplete();
    } catch (err) {
      console.error("Setup failed:", err);
      setIsProcessing(false);
      setSetupStep('Error occurred. Please try again.');
    }
  };

  const scrollCarousel = (direction: 'left' | 'right') => {
    if (carouselRef.current) {
      const scrollAmount = carouselRef.current.clientWidth * 0.8;
      carouselRef.current.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsIdentifying(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64Image = reader.result as string;
      try {
        const breed = await identifyBreedFromImage(base64Image);
        setSelectedBreed(breed);
      } catch (e) {
        console.error("Identification failed");
      }
      setIsIdentifying(false);
    };
    reader.readAsDataURL(file);
  };

  const breeds = selectedType ? BREED_DATA[selectedType] || [{ name: 'Standard', image: 'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?auto=format&fit=crop&q=80&w=400' }] : [];

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden">
        <div className="bg-gradient-to-br from-indigo-700 via-indigo-600 to-indigo-900 p-12 text-center text-white relative">
          <h2 className="text-4xl md:text-5xl font-black mb-4 tracking-tight">Personalizing Care for {pet.name}</h2>
          <p className="text-indigo-100 text-lg font-medium max-w-2xl mx-auto opacity-90">
            Tell us about {pet.name}'s species and breed so we can tailor the health and diet plans.
          </p>
        </div>

        <div className="p-8 md:p-14 space-y-16">
          <section>
            <div className="flex items-center gap-4 mb-8">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black">1</div>
              <h3 className="text-2xl font-black text-slate-800">Select Species</h3>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-4">
              {PET_TYPES.map((item) => (
                <button
                  key={item.type}
                  onClick={() => { setSelectedType(item.type); setSelectedBreed(''); }}
                  className={`flex flex-col items-center p-6 rounded-[2.5rem] border-2 transition-all ${
                    selectedType === item.type ? 'border-indigo-600 bg-indigo-50 shadow-lg' : 'border-slate-100 bg-slate-50 hover:border-indigo-200'
                  }`}
                >
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 ${item.color}`}>
                    <i className={`fas ${item.icon} text-2xl`}></i>
                  </div>
                  <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </div>
          </section>

          {selectedType && (
            <section className="animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row items-center justify-between mb-8 gap-4">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black">2</div>
                  <h3 className="text-2xl font-black text-slate-800">Select Breed</h3>
                </div>
                <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-full text-xs font-black uppercase tracking-widest hover:bg-slate-800 transition-all">
                  <i className="fas fa-magic"></i> Identify from Photo
                </button>
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
              </div>

              {isIdentifying ? (
                <div className="py-20 flex flex-col items-center justify-center bg-slate-50 rounded-[3rem] border-2 border-dashed border-indigo-200">
                  <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                  <p className="mt-4 text-indigo-600 font-bold uppercase tracking-widest">AI Breed Recognition...</p>
                </div>
              ) : (
                <div className="relative group/carousel">
                  <div ref={carouselRef} className="flex overflow-x-auto gap-6 pb-8 snap-x no-scrollbar scroll-smooth">
                    {breeds.map((breed) => (
                      <button
                        key={breed.name}
                        onClick={() => setSelectedBreed(breed.name)}
                        className={`snap-center flex-shrink-0 w-64 rounded-[3rem] overflow-hidden border-4 transition-all ${
                          selectedBreed === breed.name ? 'border-indigo-600 shadow-xl' : 'border-white hover:border-indigo-50 shadow-md'
                        }`}
                      >
                        <div className="aspect-[3/4]"><BreedImage src={breed.image} alt={breed.name} isSelected={selectedBreed === breed.name} /></div>
                        <div className={`p-4 text-center font-black uppercase tracking-widest text-xs ${selectedBreed === breed.name ? 'bg-indigo-600 text-white' : 'bg-white text-slate-700'}`}>
                          {breed.name}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </section>
          )}

          <div className="pt-8 border-t border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6">
            {isProcessing && (
              <div className="flex items-center gap-3 text-indigo-600 font-bold animate-pulse">
                <i className="fas fa-spinner fa-spin"></i>
                <span>{setupStep}</span>
              </div>
            )}
            <div className="flex-1"></div>
            <button
              disabled={!selectedType || !selectedBreed || isProcessing}
              onClick={handleSave}
              className="px-12 py-5 bg-indigo-600 text-white rounded-full font-black text-xl hover:bg-indigo-700 transition-all shadow-xl disabled:opacity-50 flex items-center gap-4"
            >
              {isProcessing ? 'Processing...' : 'Finish Pet Profile'}
              {!isProcessing && <i className="fas fa-check"></i>}
            </button>
          </div>
        </div>
      </div>
      <style>{`.no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};

export default PetSetup;

import React, { useState, useEffect } from 'react';
import { Pet, HealthMetric, DailyDietPlan } from '../types';
import HealthChart from './HealthChart';
import { getBreedAdvice, getDietaryRecommendation, getStructuredDietPlan } from '../services/geminiService';

interface DashboardProps {
  pet: Pet;
  onUpdatePet: (updatedPet: Pet) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ pet, onUpdatePet }) => {
  const [advice, setAdvice] = useState<string>(pet.breedAdvice || '');
  const [diet, setDiet] = useState<string>(pet.dietaryRecommendation || '');
  const [structuredDiet, setStructuredDiet] = useState<DailyDietPlan | null>(pet.dietPlan || null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newWeight, setNewWeight] = useState('');

  useEffect(() => {
    const fetchInfo = async () => {
      // If we have all the data cached, don't hit the API
      if (pet.breedAdvice && pet.dietaryRecommendation && pet.dietPlan) {
        setAdvice(pet.breedAdvice);
        setDiet(pet.dietaryRecommendation);
        setStructuredDiet(pet.dietPlan);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        let updatedPet = { ...pet };
        let changesMade = false;

        // Fetch sequentially to respect rate limits
        if (!pet.breedAdvice) {
          const res = await getBreedAdvice(pet);
          setAdvice(res);
          updatedPet.breedAdvice = res;
          changesMade = true;
        }

        if (!pet.dietaryRecommendation) {
          const res = await getDietaryRecommendation(pet);
          setDiet(res);
          updatedPet.dietaryRecommendation = res;
          changesMade = true;
        }

        if (!pet.dietPlan) {
          const res = await getStructuredDietPlan(pet);
          if (res) {
            setStructuredDiet(res);
            updatedPet.dietPlan = res;
            changesMade = true;
          }
        }

        if (changesMade) {
          onUpdatePet(updatedPet);
        }
      } catch (err: any) {
        console.error("Dashboard data fetch error:", err);
        setError("AI Assistant is currently busy. Some recommendations may be unavailable.");
      } finally {
        setLoading(false);
      }
    };

    fetchInfo();
  }, [pet.id]);

  const handleAddMetric = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWeight) return;

    const newMetric: HealthMetric = {
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      weight: parseFloat(newWeight),
      mood: 'Happy',
      activityLevel: 7
    };

    const updatedPet = {
      ...pet,
      metrics: [...pet.metrics, newMetric]
    };
    onUpdatePet(updatedPet);
    setNewWeight('');
  };

  const calculateDaysLeft = (dueDate: string) => {
    const [day, month, year] = dueDate.split('.');
    const due = new Date(`${year}-${month}-${day}`);
    const now = new Date();
    const diffTime = due.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const nextVaccine = pet.vaccinations
    .filter(v => !v.completedDate)
    .sort((a, b) => {
      const dateA = a.dueDate.split('.').reverse().join('-');
      const dateB = b.dueDate.split('.').reverse().join('-');
      return dateA.localeCompare(dateB);
    })[0];

  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const daysLeft = nextVaccine ? calculateDaysLeft(nextVaccine.dueDate) : null;

  return (
    <div className="space-y-6 pb-12">
      {error && (
        <div className="bg-amber-50 border border-amber-200 text-amber-800 p-4 rounded-xl flex items-center gap-3 text-sm">
          <i className="fas fa-exclamation-triangle"></i>
          {error}
        </div>
      )}

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-weight-scale text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Current Weight</p>
              <h3 className="text-2xl font-bold text-slate-800">{lastMetric?.weight || '--'} kg</h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${daysLeft !== null && daysLeft < 7 ? 'bg-rose-100 text-rose-600' : 'bg-indigo-100 text-indigo-600'}`}>
              <i className="fas fa-syringe text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Next Vaccination</p>
              <h3 className="text-xl font-bold text-slate-800">
                {nextVaccine ? (
                  <div className="flex flex-col">
                    <span>{nextVaccine.dueDate}</span>
                    <span className={`text-xs font-bold ${daysLeft !== null && daysLeft < 7 ? 'text-rose-500' : 'text-indigo-500'}`}>
                      {daysLeft !== null ? (daysLeft < 0 ? 'Overdue!' : `${daysLeft} days remaining`) : ''}
                    </span>
                  </div>
                ) : 'None scheduled'}
              </h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-paw text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Breed</p>
              <h3 className="text-2xl font-bold text-slate-800">{pet.breed}</h3>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Diet Plan */}
      <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">Daily Diet Plan</h3>
            <p className="text-slate-500 text-sm">Time-specific meal schedule for {pet.name}</p>
          </div>
          <div className="flex gap-4">
            <div className="bg-blue-50 px-4 py-2 rounded-xl border border-blue-100 flex items-center gap-2">
              <i className="fas fa-droplet text-blue-500"></i>
              <span className="text-xs font-bold text-blue-700">{structuredDiet?.waterIntake || '800ml/day'}</span>
            </div>
            {structuredDiet?.totalCalories && (
              <div className="bg-emerald-50 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                <i className="fas fa-bolt text-emerald-500"></i>
                <span className="text-xs font-bold text-emerald-700">{structuredDiet.totalCalories}</span>
              </div>
            )}
          </div>
        </div>

        {loading && !structuredDiet ? (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[1, 2, 3, 4].map(i => (
              <div key={i} className="h-32 bg-slate-50 rounded-2xl animate-pulse"></div>
            ))}
          </div>
        ) : structuredDiet ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
            {structuredDiet.meals.map((meal, idx) => (
              <div key={idx} className="bg-slate-50 border border-slate-100 p-6 rounded-3xl group hover:border-indigo-200 transition-all hover:shadow-lg hover:shadow-indigo-50/50">
                <div className="flex justify-between items-start mb-4">
                  <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-1 rounded-md">
                    {meal.time}
