const PetSetup: React.FC<PetSetupProps> = ({ pet, onUpdate, onComplete }) => {
  const [selectedType, setSelectedType] = useState<PetType | null>(null);
  const [selectedBreed, setSelectedBreed] = useState<string>('');
  const [isIdentifying, setIsIdentifying] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [setupStep, setSetupStep] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const carouselRef = useRef<HTMLDivElement>(null);

  const handleSave = async () => {
    if (!selectedType || !selectedBreed) return;
    setIsProcessing(true);

    const tempPet: Pet = {
      ...pet,
      type: selectedType,
      breed: selectedBreed
    };

    try {
      setSetupStep('Calculating breed health targets...');
      const { idealWeight, idealHeight } = await getBreedMetrics(tempPet);

      setSetupStep('Customizing vaccination schedule...');
      const vaccines = await getRecommendedVaccinations(tempPet, ['23.04.2026', '22.05.2026']);

      setSetupStep('Designing dietary blueprint...');
      const dietPlan = await getStructuredDietPlan(tempPet);

      setSetupStep('Gathering breed-specific care tips...');
      const breedAdvice = await getBreedAdvice(tempPet);

      setSetupStep('Finalizing nutritional recommendations...');
      const dietRec = await getDietaryRecommendation(tempPet);

      // Generate mock historical data to show "difference in the chart"
      const now = new Date();
      const mockMetrics: HealthMetric[] = [
        {
          date: new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          weight: idealWeight * 0.9,
          height: idealHeight * 0.95,
          mood: 'Happy',
          activityLevel: 8
