        {
          date: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          weight: idealWeight * 0.95,
          height: idealHeight * 0.98,
          mood: 'Energetic',
          activityLevel: 9
        },
        {
          date: now.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          weight: idealWeight,
          height: idealHeight,
          mood: 'Happy',
          activityLevel: 7
        }
      ];

      onUpdate({
        ...tempPet,
        vaccinations: vaccines.length > 0 ? vaccines : pet.vaccinations,
        dietPlan: dietPlan || pet.dietPlan,
        breedAdvice: breedAdvice || undefined,
        dietaryRecommendation: dietRec || undefined,
        standardHeight: idealHeight,
        metrics: mockMetrics
