import React, { useState, useEffect } from 'react';
import { Pet, HealthMetric, DailyDietPlan } from '../types';
import HealthChart from './HealthChart';
import { getBreedAdvice, getDietaryRecommendation, getStructuredDietPlan } from '../services/geminiService';

interface DashboardProps {
  pet: Pet;
  onUpdatePet: (updatedPet: Pet) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ pet, onUpdatePet }) => {
  const [advice, setAdvice] = useState<string>(pet.breedAdvice || '');
  const [diet, setDiet] = useState<string>(pet.dietaryRecommendation || '');
  const [structuredDiet, setStructuredDiet] = useState<DailyDietPlan | null>(pet.dietPlan || null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newWeight, setNewWeight] = useState('');
  const [newHeight, setNewHeight] = useState('');

  useEffect(() => {
    const fetchInfo = async () => {
      if (pet.breedAdvice && pet.dietaryRecommendation && pet.dietPlan) {
        setAdvice(pet.breedAdvice);
        setDiet(pet.dietaryRecommendation);
        setStructuredDiet(pet.dietPlan);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        let updatedPet = { ...pet };
        let changesMade = false;

        if (!pet.breedAdvice) {
          const res = await getBreedAdvice(pet);
          setAdvice(res);
          updatedPet.breedAdvice = res;
          changesMade = true;
        }

        if (!pet.dietaryRecommendation) {
          const res = await getDietaryRecommendation(pet);
          setDiet(res);
          updatedPet.dietaryRecommendation = res;
          changesMade = true;
        }

        if (!pet.dietPlan) {
          const res = await getStructuredDietPlan(pet);
          if (res) {
            setStructuredDiet(res);
            updatedPet.dietPlan = res;
            changesMade = true;
          }
        }

        if (changesMade) {
          onUpdatePet(updatedPet);
        }
      } catch (err: any) {
        console.error("Dashboard data fetch error:", err);
        setError("AI Assistant is currently busy. Some recommendations may be unavailable.");
      } finally {
        setLoading(false);
      }
    };

    fetchInfo();
