import { GoogleGenAI, Type } from "@google/genai";
import { Pet, DailyDietPlan, Vaccination } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

/**
 * Robust wrapper for Gemini API calls to handle 429 Rate Limit errors with exponential backoff.
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 4): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error.message || "";
      // Check for 429 (Rate Limit) or quota exhaustion
      if ((errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED")) && i < maxRetries - 1) {
        const waitTime = (i + 1) * 3000; // Increased delay: 3s, 6s, 9s...
        console.warn(`Gemini API rate limited. Retrying in ${waitTime}ms...`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  return callWithRetry(async () => {
    const imagePart = {
      inlineData: {
        mimeType: 'image/jpeg',
        data: base64Image.split(',')[1],
      },
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          imagePart, 
          { text: "Identify the specific breed of the pet in this image. Return ONLY the breed name as a plain string (e.g., 'Golden Retriever')." }
        ] 
      },
    });

    return response.text?.trim() || "Unknown Breed";
  });
};

/**
 * Batches all pet insights into a SINGLE request to save quota.
 */
export const generateFullPetProfile = async (pet: { breed: string, type: string }) => {
  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a comprehensive health and care profile for a ${pet.breed} ${pet.type}. 
      Include ideal adult metrics, essential vaccinations, a 3-meal daily diet plan, and breed-specific care advice.
      Output the result as a strictly formatted JSON object.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            idealWeight: { type: Type.NUMBER, description: "Average adult weight in kg" },
            idealHeight: { type: Type.NUMBER, description: "Average adult height in cm" },
            breedAdvice: { type: Type.STRING, description: "Concise expert care tips" },
            dietaryRecommendation: { type: Type.STRING, description: "Nutritional overview and foods to avoid" },
            dietPlan: {
              type: Type.OBJECT,
              properties: {
                meals: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING },
                      label: { type: Type.STRING },
                      quantity: { type: Type.STRING },
                      notes: { type: Type.STRING }
                    },
                    required: ["time", "label", "quantity", "notes"]
                  }
                },
                waterIntake: { type: Type.STRING },
                totalCalories: { type: Type.STRING }
              },
              required: ["meals", "waterIntake"]
            },
            vaccinations: {
              type: Type.ARRAY,
              items: { type: Type.STRING, description: "Name of essential vaccine" }
            }
          },
          required: ["idealWeight", "idealHeight", "breedAdvice", "dietaryRecommendation", "dietPlan", "vaccinations"]
        }
      }
    });

    const data = JSON.parse(response.text.trim());

    // Map vaccinations to the expected format
    const vaccines: Vaccination[] = data.vaccinations.map((name: string, index: number) => ({
      id: `v-${Date.now()}-${index}`,
      name,
      dueDate: index === 0 ? '23.04.2026' : '22.05.2026',
      isRequired: true
    }));

    return { ...data, vaccinations: vaccines };
  });
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  const contextPrompt = petContext 
    ? `You are PawPulse, an expert AI pet care assistant for ${petContext.name}, a ${petContext.breed} ${petContext.type}.`
    : "You are PawPulse, an expert AI pet care assistant.";

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: contextPrompt },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `User: ${message}` }
      ],
    });
    return response.text;
  });
};

