const PetSetup: React.FC<PetSetupProps> = ({ pet, onUpdate, onComplete }) => {
  const [selectedType, setSelectedType] = useState<PetType | null>(null);
  const [selectedBreed, setSelectedBreed] = useState<string>('');
  const [isIdentifying, setIsIdentifying] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [setupStep, setSetupStep] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const carouselRef = useRef<HTMLDivElement>(null);

  const handleSave = async () => {
    if (!selectedType || !selectedBreed) return;
    setIsProcessing(true);
    setSetupStep('Generating personalized pet profile...');

    try {
      const insights = await generateFullPetProfile({ breed: selectedBreed, type: selectedType });

      const now = new Date();
      const mockMetrics: HealthMetric[] = [
        {
          date: new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          weight: insights.idealWeight * 0.9,
          height: insights.idealHeight * 0.95,
          mood: 'Happy',
          activityLevel: 8
        },
        {
          date: now.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          weight: insights.idealWeight,
          height: insights.idealHeight,
          mood: 'Happy',
          activityLevel: 7
        }
      ];

      onUpdate({
        ...pet,
        type: selectedType,
        breed: selectedBreed,
        vaccinations: insights.vaccinations,
        dietPlan: insights.dietPlan,
        breedAdvice: insights.breedAdvice,
        dietaryRecommendation: insights.dietaryRecommendation,
        standardHeight: insights.idealHeight,
        metrics: mockMetrics
      });

      setIsProcessing(false);
      onComplete();
    } catch (err) {
      console.error("Setup failed:", err);
      setIsProcessing(false);
      setSetupStep('AI is currently busy. Please try again in 30 seconds.');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsIdentifying(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64Image = reader.result as string;
      try {
        const breed = await identifyBreedFromImage(base64Image);
        setSelectedBreed(breed);
      } catch (e) {
        console.error("Identification failed");
      }
      setIsIdentifying(false);
    };
    reader.readAsDataURL(file);
  };

  const breeds = selectedType ? BREED_DATA[selectedType] || [{ name: 'Standard', image: 'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?auto=format&fit=crop&q=80&w=400' }] : [];

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden">
        <div className="bg-gradient-to-br from-indigo-700 via-indigo-600 to-indigo-900 p-12 text-center text-white relative">
          <h2 className="text-4xl md:text-5xl font-black mb-4 tracking-tight">Personalizing Care for {pet.name}</h2>
          <p className="text-indigo-100 text-lg font-medium max-w-2xl mx-auto opacity-90">
            One quick setup to unlock AI-powered health tracking.
          </p>
        </div>

        <div className="p-8 md:p-14 space-y-16">
          <section>
            <div className="flex items-center gap-4 mb-8">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black">1</div>
              <h3 className="text-2xl font-black text-slate-800">Select Species</h3>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-4">
              {PET_TYPES.map((item) => (
                <button
                  key={item.type}
                  onClick={() => { setSelectedType(item.type); setSelectedBreed(''); }}
                  className={`flex flex-col items-center p-6 rounded-[2.5rem] border-2 transition-all ${
                    selectedType === item.type ? 'border-indigo-600 bg-indigo-50 shadow-lg' : 'border-slate-100 bg-slate-50 hover:border-indigo-200'
                  }`}
                >
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 ${item.color}`}>
                    <i className={`fas ${item.icon} text-2xl`}></i>
                  </div>
                  <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </div>
          </section>

          {selectedType && (
            <section className="animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row items-center justify-between mb-8 gap-4">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black">2</div>
                  <h3 className="text-2xl font-black text-slate-800">Select Breed</h3>
                </div>
                <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-full text-xs font-black uppercase tracking-widest hover:bg-slate-800 transition-all">
                  <i className="fas fa-magic"></i> Identify from Photo
                </button>
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
              </div>

              {isIdentifying ? (
                <div className="py-20 flex flex-col items-center justify-center bg-slate-50 rounded-[3rem] border-2 border-dashed border-indigo-200">
                  <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                  <p className="mt-4 text-indigo-600 font-bold uppercase tracking-widest">AI Breed Recognition...</p>
                </div>
              ) : (
                <div className="relative group/carousel">
                  <div ref={carouselRef} className="flex overflow-x-auto gap-6 pb-8 snap-x no-scrollbar scroll-smooth">
                    {breeds.map((breed) => (
                      <button
                        key={breed.name}
                        onClick={() => setSelectedBreed(breed.name)}
                        className={`snap-center flex-shrink-0 w-64 rounded-[3rem] overflow-hidden border-4 transition-all ${
                          selectedBreed === breed.name ? 'border-indigo-600 shadow-xl' : 'border-white hover:border-indigo-50 shadow-md'
                        }`}
                      >
                        <div className="aspect-[3/4]"><BreedImage src={breed.image} alt={breed.name} isSelected={selectedBreed === breed.name} /></div>
                        <div className={`p-4 text-center font-black uppercase tracking-widest text-xs ${selectedBreed === breed.name ? 'bg-indigo-600 text-white' : 'bg-white text-slate-700'}`}>
                          {breed.name}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </section>
          )}

          <div className="pt-8 border-t border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6">
            {isProcessing && (
              <div className="flex items-center gap-3 text-indigo-600 font-bold animate-pulse">
                <i className="fas fa-spinner fa-spin"></i>
                <span>{setupStep}</span>
              </div>
            )}
            <div className="flex-1"></div>
            <button
              disabled={!selectedType || !selectedBreed || isProcessing}
              onClick={handleSave}
              className="px-12 py-5 bg-indigo-600 text-white rounded-full font-black text-xl hover:bg-indigo-700 transition-all shadow-xl disabled:opacity-50 flex items-center gap-4"
            >
              {isProcessing ? 'Processing...' : 'Finish Pet Profile'}
              {!isProcessing && <i className="fas fa-check"></i>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

