              <div key={idx} className="bg-slate-50 border border-slate-100 p-6 rounded-3xl group hover:border-indigo-200 transition-all hover:shadow-lg hover:shadow-indigo-50/50">
                <div className="flex justify-between items-start mb-4">
                  <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-1 rounded-md">
                    {meal.time}
