                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center text-slate-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                    <i className={`fas ${
                      meal.label.toLowerCase().includes('breakfast') ? 'fa-sun' : 
                      meal.label.toLowerCase().includes('lunch') ? 'fa-cloud-sun' : 
                      meal.label.toLowerCase().includes('dinner') ? 'fa-moon' : 'fa-cookie-bite'
                    }`}></i>
                  </div>
                </div>
                <h4 className="font-bold text-slate-800 mb-1">{meal.label}</h4>
                <p className="text-sm font-black text-indigo-500 mb-2">{meal.quantity}</p>
                <p className="text-xs text-slate-500 leading-relaxed italic">{meal.notes}</p>
