import { GoogleGenAI, Type } from "@google/genai";
import { Pet, DailyDietPlan, Vaccination } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

// Global tracking to prevent hammering the API after a 429
let globalCooldownUntil = 0;

export const isApiCoolingDown = () => Date.now() < globalCooldownUntil;
export const getRemainingCooldown = () => Math.max(0, Math.ceil((globalCooldownUntil - Date.now()) / 1000));

/**
 * Robust wrapper for Gemini API calls to handle 429 Rate Limit errors with exponential backoff.
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  if (isApiCoolingDown()) {
    throw new Error(`API is cooling down. Please wait ${getRemainingCooldown()} seconds.`);
  }

  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error.message || "";
      const isRateLimit = errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED");

      if (isRateLimit) {
        // Set a global cooldown of 60 seconds if we hit a hard limit
        globalCooldownUntil = Date.now() + 60000;

        if (i < maxRetries - 1) {
          const waitTime = (Math.pow(2, i) * 5000) + (Math.random() * 1000); // 5s, 10s... + jitter
          console.warn(`Gemini API rate limited. Retrying in ${Math.round(waitTime)}ms...`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          // Reset cooldown if we are retrying internally
          globalCooldownUntil = 0;
          continue;
        }
      }
      throw error;
    }
  }
  throw lastError;
}

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  return callWithRetry(async () => {
    const imagePart = {
      inlineData: {
        mimeType: 'image/jpeg',
        data: base64Image.split(',')[1],
      },
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          imagePart, 
          { text: "Identify the specific breed of the pet in this image. Return ONLY the breed name as a plain string (e.g., 'Golden Retriever')." }
        ] 
      },
    });

    return response.text?.trim() || "Unknown Breed";
  });
};

/**
 * Batches all pet insights into a SINGLE request to save quota.
 */
export const generateFullPetProfile = async (pet: { breed: string, type: string }) => {
  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a comprehensive health and care profile for a ${pet.breed} ${pet.type}. 
      Include ideal adult metrics, essential vaccinations, a 3-meal daily diet plan, and breed-specific care advice.
      Output the result as a strictly formatted JSON object.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            idealWeight: { type: Type.NUMBER, description: "Average adult weight in kg" },
            idealHeight: { type: Type.NUMBER, description: "Average adult height in cm" },
            breedAdvice: { type: Type.STRING, description: "Concise expert care tips" },
            dietaryRecommendation: { type: Type.STRING, description: "Nutritional overview and foods to avoid" },
            dietPlan: {
              type: Type.OBJECT,
              properties: {
                meals: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING },
                      label: { type: Type.STRING },
                      quantity: { type: Type.STRING },
                      notes: { type: Type.STRING }
                    },
                    required: ["time", "label", "quantity", "notes"]
                  }
                },
                waterIntake: { type: Type.STRING },
                totalCalories: { type: Type.STRING }
              },
              required: ["meals", "waterIntake"]
            },
            vaccinations: {
              type: Type.ARRAY,
              items: { type: Type.STRING, description: "Name of essential vaccine" }
            }
          },
          required: ["idealWeight", "idealHeight", "breedAdvice", "dietaryRecommendation", "dietPlan", "vaccinations"]
        }
      }
    });

    const data = JSON.parse(response.text.trim());

    // Map vaccinations to the expected format
    const vaccines: Vaccination[] = data.vaccinations.map((name: string, index: number) => ({
      id: `v-${Date.now()}-${index}`,
      name,
      dueDate: index === 0 ? '23.04.2026' : '22.05.2026',
      isRequired: true
    }));

    return { ...data, vaccinations: vaccines };
  });
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  const contextPrompt = petContext 
    ? `You are PawPulse, an expert AI pet care assistant for ${petContext.name}, a ${petContext.breed} ${petContext.type}.`
    : "You are PawPulse, an expert AI pet care assistant.";

  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: contextPrompt },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `User: ${message}` }
      ],
    });
    return response.text;
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { Pet, HealthMetric, DailyDietPlan } from '../types';
import HealthChart from './HealthChart';
import { generateFullPetProfile, isApiCoolingDown, getRemainingCooldown } from '../services/geminiService';

interface DashboardProps {
  pet: Pet;
  onUpdatePet: (updatedPet: Pet) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ pet, onUpdatePet }) => {
  const [advice, setAdvice] = useState<string>(pet.breedAdvice || '');
  const [diet, setDiet] = useState<string>(pet.dietaryRecommendation || '');
  const [structuredDiet, setStructuredDiet] = useState<DailyDietPlan | null>(pet.dietPlan || null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newWeight, setNewWeight] = useState('');
  const [newHeight, setNewHeight] = useState('');
  const [cooldown, setCooldown] = useState(0);

  const fetchMissingInfo = useCallback(async (force = false) => {
    // If we have all data, don't hit the API unless forced
    if (!force && pet.breedAdvice && pet.dietaryRecommendation && pet.dietPlan && pet.vaccinations.length > 0) {
      setAdvice(pet.breedAdvice);
      setDiet(pet.dietaryRecommendation);
      setStructuredDiet(pet.dietPlan);
      return;
    }

    if (isApiCoolingDown() && !force) {
      setError(`Sync paused. AI is cooling down...`);
      setCooldown(getRemainingCooldown());
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const insights = await generateFullPetProfile({ breed: pet.breed, type: pet.type });

      const updatedPet = {
        ...pet,
        breedAdvice: insights.breedAdvice,
        dietaryRecommendation: insights.dietaryRecommendation,
        dietPlan: insights.dietPlan,
        vaccinations: pet.vaccinations.length > 0 ? pet.vaccinations : insights.vaccinations,
        standardHeight: insights.idealHeight
      };

      setAdvice(insights.breedAdvice);
      setDiet(insights.dietaryRecommendation);
      setStructuredDiet(insights.dietPlan);
      onUpdatePet(updatedPet);
      setError(null);

    } catch (err: any) {
      console.error("Dashboard refresh error:", err);
      setError("AI limits reached. Syncing will resume automatically.");
      setCooldown(getRemainingCooldown() || 60);
    } finally {
      setLoading(false);
    }
  }, [pet, onUpdatePet]);

  useEffect(() => {
    fetchMissingInfo();

    const timer = setInterval(() => {
      if (isApiCoolingDown()) {
        setCooldown(getRemainingCooldown());
      } else {
        setCooldown(0);
      }
    }, 1000);

    return () => clearInterval(timer);
  }, [pet.id]);

  const handleAddMetric = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newWeight || !newHeight) return;

    const newMetric: HealthMetric = {
      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      weight: parseFloat(newWeight),
      height: parseFloat(newHeight),
      mood: 'Happy',
      activityLevel: 7
    };

    onUpdatePet({
      ...pet,
      metrics: [...pet.metrics, newMetric]
    });
    setNewWeight('');
    setNewHeight('');
  };

  const calculateDaysLeft = (dueDate: string) => {
    const [day, month, year] = dueDate.split('.');
    const due = new Date(`${year}-${month}-${day}`);
    const now = new Date();
    const diffTime = due.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const nextVaccine = pet.vaccinations
    .filter(v => !v.completedDate)
    .sort((a, b) => {
      const dateA = a.dueDate.split('.').reverse().join('-');
      const dateB = b.dueDate.split('.').reverse().join('-');
      return dateA.localeCompare(dateB);
    })[0];

  const lastMetric = pet.metrics[pet.metrics.length - 1];
  const firstMetric = pet.metrics[0];
  const weightDiff = lastMetric && firstMetric ? (lastMetric.weight - firstMetric.weight).toFixed(1) : '0';
  const daysLeft = nextVaccine ? calculateDaysLeft(nextVaccine.dueDate) : null;

  return (
    <div className="space-y-6 pb-12">
      {error && (
        <div className="bg-amber-50 border border-amber-200 text-amber-800 p-4 rounded-2xl flex items-center justify-between gap-3 text-sm shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-amber-200 rounded-full flex items-center justify-center animate-pulse">
              <i className="fas fa-robot"></i>
            </div>
            <span>
              {error} {cooldown > 0 && `(${cooldown}s)`}
            </span>
          </div>
          <button 
            disabled={loading || cooldown > 0}
            onClick={() => fetchMissingInfo(true)}
            className="px-4 py-1.5 bg-white border border-amber-300 rounded-full text-xs font-black uppercase tracking-widest hover:bg-amber-100 disabled:opacity-30 transition-all"
          >
            {loading ? 'Syncing...' : 'Retry Now'}
          </button>
        </div>
      )}

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-weight-scale text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Weight</p>
              <h3 className="text-2xl font-bold text-slate-800">{lastMetric?.weight || '--'} kg</h3>
              <p className={`text-[10px] font-black ${parseFloat(weightDiff) >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                {parseFloat(weightDiff) >= 0 ? '+' : ''}{weightDiff} kg total progress
              </p>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-cyan-100 text-cyan-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-ruler-vertical text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Height</p>
              <h3 className="text-2xl font-bold text-slate-800">{lastMetric?.height || pet.standardHeight || '--'} cm</h3>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Standard for breed</p>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${daysLeft !== null && daysLeft < 7 ? 'bg-rose-100 text-rose-600' : 'bg-indigo-100 text-indigo-600'}`}>
              <i className="fas fa-syringe text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Next Vax</p>
              <h3 className="text-xl font-bold text-slate-800">
                {nextVaccine ? (
                  <div className="flex flex-col">
                    <span>{nextVaccine.dueDate}</span>
                    <span className={`text-[10px] font-bold ${daysLeft !== null && daysLeft < 7 ? 'text-rose-500' : 'text-indigo-500'}`}>
                      {daysLeft !== null ? (daysLeft < 0 ? 'Overdue!' : `${daysLeft}d left`) : ''}
                    </span>
                  </div>
                ) : 'None'}
              </h3>
            </div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center">
              <i className="fas fa-paw text-xl"></i>
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">Breed</p>
              <h3 className="text-lg font-bold text-slate-800 truncate">{pet.breed}</h3>
            </div>
          </div>
        </div>
      </div>

      {/* Daily Diet Plan */}
      <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">Daily Diet Plan</h3>
            <p className="text-slate-500 text-sm">Time-specific meal schedule for {pet.name}</p>
          </div>
          <div className="flex gap-4">
            <div className="bg-blue-50 px-4 py-2 rounded-xl border border-blue-100 flex items-center gap-2">
              <i className="fas fa-droplet text-blue-500"></i>
              <span className="text-xs font-bold text-blue-700">{structuredDiet?.waterIntake || '800ml/day'}</span>
            </div>
            {structuredDiet?.totalCalories && (
              <div className="bg-emerald-50 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                <i className="fas fa-bolt text-emerald-500"></i>
                <span className="text-xs font-bold text-emerald-700">{structuredDiet.totalCalories}</span>
              </div>
            )}
          </div>
        </div>

        {loading && !structuredDiet ? (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[1, 2, 3, 4].map(i => (
              <div key={i} className="h-32 bg-slate-50 rounded-2xl animate-pulse"></div>
            ))}
          </div>
        ) : structuredDiet ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
            {structuredDiet.meals.map((meal, idx) => (
              <div key={idx} className="bg-slate-50 border border-slate-100 p-6 rounded-3xl group hover:border-indigo-200 transition-all hover:shadow-lg hover:shadow-indigo-50/50">
                <div className="flex justify-between items-start mb-4">
                  <span className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-1 rounded-md">
                    {meal.time}
                  </span>
                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center text-slate-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                    <i className={`fas ${
                      meal.label.toLowerCase().includes('breakfast') ? 'fa-sun' : 
                      meal.label.toLowerCase().includes('lunch') ? 'fa-cloud-sun' : 
                      meal.label.toLowerCase().includes('dinner') ? 'fa-moon' : 'fa-cookie-bite'
                    }`}></i>
                  </div>
                </div>
                <h4 className="font-bold text-slate-800 mb-1">{meal.label}</h4>
                <p className="text-sm font-black text-indigo-500 mb-2">{meal.quantity}</p>
                <p className="text-xs text-slate-500 leading-relaxed italic">{meal.notes}</p>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-10 text-slate-400 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-100">
            <i className="fas fa-utensils text-3xl mb-2 opacity-20"></i>
            <p className="text-sm">Generation paused due to AI traffic limit.</p>
            <button 
              onClick={() => fetchMissingInfo(true)}
              className="mt-4 text-xs font-black text-indigo-600 uppercase tracking-widest underline"
            >
              Check Availability
            </button>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex flex-col md:flex-row items-center justify-between mb-6 gap-4">
