/**
 * Cache management for breed profiles
 */
const getCachedProfile = (breed: string) => {
  const saved = localStorage.getItem(`breed_cache_${breed}`);
  return saved ? JSON.parse(saved) : null;
};

const setCachedProfile = (breed: string, data: any) => {
  localStorage.setItem(`breed_cache_${breed}`, JSON.stringify(data));
};

/**
 * Robust wrapper for Gemini API calls to handle 429 Rate Limit errors.
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 2): Promise<T> {
  if (isApiCoolingDown()) {
    throw new Error(`Quota limit reached. Please wait ${getRemainingCooldown()}s.`);
  }

  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error.message || "";
      const isRateLimit = errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED");

      if (isRateLimit) {
        // Set a global cooldown of 45 seconds if we hit a limit
        globalCooldownUntil = Date.now() + 45000;

        if (i < maxRetries - 1) {
          const waitTime = (Math.pow(2, i) * 8000) + (Math.random() * 2000); 
          await new Promise(resolve => setTimeout(resolve, waitTime));
          globalCooldownUntil = 0;
          continue;
        }
      }
      throw error;
    }
  }
  throw lastError;
}

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  return callWithRetry(async () => {
    const dataPart = base64Image.split(',')[1];
    if (!dataPart) throw new Error("Invalid image format.");

    const imagePart = {
      inlineData: {
        mimeType: 'image/jpeg',
        data: dataPart,
      },
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          imagePart, 
          { text: "Identify the specific breed of the pet in this image. Return ONLY the breed name as a plain string. If you cannot identify it, return 'Unknown'." }
        ] 
      },
    });

    const breed = response.text?.trim() || "Unknown";
    return breed === "Unknown" ? "Mixed Breed" : breed;
  });
};

export const generateFullPetProfile = async (pet: { breed: string, type: string }) => {
  // 1. Check Pre-baked Data First
  if (PRE_BAKED_PROFILES[pet.breed]) {
    const data = PRE_BAKED_PROFILES[pet.breed];
    const vaccines = data.vaccinations.map((name: string, index: number) => ({
      id: `v-baked-${Date.now()}-${index}`,
      name,
      dueDate: '20.06.2025',
      isRequired: true
    }));
    return { ...data, vaccinations: vaccines };
  }

  // 2. Check Local Cache
  const cached = getCachedProfile(pet.breed);
  if (cached) return cached;

  // 3. Call API if not cached
  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide expert pet care data for a ${pet.breed} ${pet.type}. Include adult metrics (weight kg, height cm), care advice, dietary recommendations, 3-meal plan, and required vaccinations. Output JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            idealWeight: { type: Type.NUMBER },
            idealHeight: { type: Type.NUMBER },
            breedAdvice: { type: Type.STRING },
            dietaryRecommendation: { type: Type.STRING },
            dietPlan: {
              type: Type.OBJECT,
              properties: {
                meals: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING },
                      label: { type: Type.STRING },
                      quantity: { type: Type.STRING },
                      notes: { type: Type.STRING }
                    },
                    required: ["time", "label", "quantity", "notes"]
                  }
                },
                waterIntake: { type: Type.STRING },
                totalCalories: { type: Type.STRING }
              },
              required: ["meals", "waterIntake"]
            },
            vaccinations: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["idealWeight", "idealHeight", "breedAdvice", "dietaryRecommendation", "dietPlan", "vaccinations"]
        }
      }
    });

    const data = JSON.parse(response.text.trim());
    const vaccines = data.vaccinations.map((name: string, index: number) => ({
      id: `v-${Date.now()}-${index}`,
      name,
      dueDate: '15.08.2025',
      isRequired: true
    }));

    const fullProfile = { ...data, vaccinations: vaccines };

    // Cache for future use
    setCachedProfile(pet.breed, fullProfile);

    return fullProfile;
  });
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  return callWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { text: `System: You are PawPulse AI for ${petContext?.name || 'a pet'}.` },
        ...history.map(h => ({ text: `${h.role}: ${h.content}` })),
        { text: `User: ${message}` }
      ],
    });
    return response.text;
  });
};

