const getGenericFallbackProfile = (type: string, breed: string) => {
  return {
    idealWeight: type === 'Dog' ? 20 : type === 'Cat' ? 5 : 0.5,
    idealHeight: type === 'Dog' ? 45 : type === 'Cat' ? 25 : 15,
    breedAdvice: `As a ${breed}, your pet requires a balanced routine of exercise and rest. For specific health concerns, consult a local veterinarian. Maintain a clean living environment and regular social interaction.`,
    dietaryRecommendation: `A balanced diet rich in essential nutrients for a ${type}. Ensure constant access to fresh water. Avoid processed human foods and toxic items like chocolate or onions.`,
    dietPlan: {
