const getCachedProfile = (breed: string) => {
  const saved = localStorage.getItem(`breed_cache_${breed}`);
  return saved ? JSON.parse(saved) : null;
};

const setCachedProfile = (breed: string, data: any) => {
  localStorage.setItem(`breed_cache_${breed}`, JSON.stringify(data));
};

async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 2): Promise<T> {
  if (isApiCoolingDown()) {
    throw new Error(`Quota limit reached. Please wait ${getRemainingCooldown()}s.`);
  }

  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error.message || "";
      const isRateLimit = errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED");

      if (isRateLimit) {
        globalCooldownUntil = Date.now() + 60000; // 1 minute cooldown
        if (i < maxRetries - 1) {
          await new Promise(resolve => setTimeout(resolve, 5000));
          globalCooldownUntil = 0;
          continue;
        }
      }
      throw error;
    }
  }
  throw lastError;
}

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  try {
    return await callWithRetry(async () => {
      const dataPart = base64Image.split(',')[1];
      if (!dataPart) throw new Error("Invalid image format.");

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { 
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: dataPart } }, 
            { text: "Identify the breed of the pet. Return ONLY the breed name string." }
          ] 
        },
      });
      return response.text?.trim() || "Mixed Breed";
    });
  } catch (e) {
    console.warn("AI Identification failed, falling back to manual selection UI.");
    return "Unknown Breed"; // UI will handle this by showing manual selector
  }
};

export const generateFullPetProfile = async (pet: { breed: string, type: string }) => {
  // 1. Check Pre-baked Data First
  if (PRE_BAKED_PROFILES[pet.breed]) {
    const data = PRE_BAKED_PROFILES[pet.breed];
    return { 
      ...data, 
      vaccinations: data.vaccinations.map((name: string, index: number) => ({
        id: `v-prebaked-${Date.now()}-${index}`, name, dueDate: '20.12.2025', isRequired: true
      }))
    };
  }

  // 2. Check Local Cache
  const cached = getCachedProfile(pet.breed);
  if (cached) return cached;

  // 3. Attempt API call
  try {
    const result = await callWithRetry(async () => {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Provide expert pet care data for a ${pet.breed} ${pet.type}. Include metrics, care tips, diet, and vaccinations. JSON format.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              idealWeight: { type: Type.NUMBER }, idealHeight: { type: Type.NUMBER },
              breedAdvice: { type: Type.STRING }, dietaryRecommendation: { type: Type.STRING },
              dietPlan: {
                type: Type.OBJECT,
                properties: {
                  meals: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { time: { type: Type.STRING }, label: { type: Type.STRING }, quantity: { type: Type.STRING }, notes: { type: Type.STRING } }, required: ["time", "label", "quantity", "notes"] } },
                  waterIntake: { type: Type.STRING }, totalCalories: { type: Type.STRING }
                }, required: ["meals", "waterIntake"]
              },
              vaccinations: { type: Type.ARRAY, items: { type: Type.STRING } }
            }, required: ["idealWeight", "idealHeight", "breedAdvice", "dietaryRecommendation", "dietPlan", "vaccinations"]
          }
        }
      });
      return JSON.parse(response.text.trim());
    });

    const fullProfile = { 
      ...result, 
      vaccinations: result.vaccinations.map((name: string, index: number) => ({
        id: `v-ai-${Date.now()}-${index}`, name, dueDate: '15.01.2026', isRequired: true
      }))
    };
    setCachedProfile(pet.breed, fullProfile);
    return fullProfile;
  } catch (err) {
    console.warn("AI profile generation failed, using standard fallback profile.");
    // 4. Return Smart Fallback if API fails
    const fallback = getGenericFallbackProfile(pet.type, pet.breed);
    return {
      ...fallback,
      vaccinations: fallback.vaccinations.map((name, index) => ({
        id: `v-fallback-${Date.now()}-${index}`, name, dueDate: '01.01.2026', isRequired: true
      }))
    };
  }
};

export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
