async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 1): Promise<T> {
  if (isApiCoolingDown()) {
    throw new Error(`AI Limit Reached. Please wait ${getRemainingCooldown()}s.`);
  }

  try {
    return await fn();
  } catch (error: any) {
    const errorMsg = error.message?.toLowerCase() || "";
    // If it's a quota error (429), set a cooldown
    if (errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("limit") || errorMsg.includes("exhausted")) {
      globalCooldownUntil = Date.now() + 30000; // 30s cooling for better UX
    }
    throw error;
  }
}

export const identifyBreedFromImage = async (base64Image: string): Promise<string> => {
  try {
    return await callWithRetry(async () => {
      const dataPart = base64Image.split(',')[1];
      if (!dataPart) return "Mixed Breed";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{
          role: 'user',
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: dataPart } },
            { text: "Identify pet breed name ONLY. If multiple, name the most prominent one." }
          ]
        }],
      });
      return response.text?.trim() || "Mixed Breed";
    });
  } catch (e) {
    return "Unknown Breed";
  }
};

