export const chatWithAssistant = async (history: {role: string, content: string}[], message: string, petContext?: Pet) => {
  try {
    return await callWithRetry(async () => {
      // Map history to the correct Gemini format (user/model)
      const mappedHistory = history.map(h => ({
        role: h.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: h.content }]
      }));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...mappedHistory,
          { role: 'user', parts: [{ text: message }] }
        ],
        config: {
          systemInstruction: `You are PawPulse AI, a professional and empathetic pet health assistant. You are currently helping with a ${petContext?.breed || 'pet'} named ${petContext?.name || 'the pet'}. Provide concise, actionable health advice. IF THE USER MENTIONS FEVER, SYMPTOMS OF PAIN, OR SERIOUS ILLNESS, STRONGLY ADVISE VISITING A VET IMMEDIATELY.`,
        }
      });
      return response.text;
    });
  } catch (err: any) {
    if (err.message?.includes("wait")) {
      return `I'm currently handling a lot of requests. Let's talk again in a few seconds!`;
    }
    console.error("Chat Error:", err);
    return "I'm having a bit of trouble connecting to my brain right now. Please try again in a moment!";
  }
};

